def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op_c = 0
    my_d = 0
    for me, opp in history:
        if opp == 'C':
            op_c += 1
        if me == 'D':
            my_d += 1

    op_d = n - op_c

    if n >= 99:
        return 'D'

    if op_c >= n - max(1, n // 10):
        if history[-1][1] == 'D':
            return 'D'
        if n >= 85 and op_d == 0:
            return 'D'
        if n >= 90 and op_d <= 2:
            return 'D'
        return 'C'

    if op_c <= n // 3:
        if op_d > n * 0.8:
            return 'D'
        if history[-1][0] == 'D' and history[-1][1] == 'D':
            return 'C'
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    last_me, last_op = history[-1]
    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if n > 85:
        if rng.random() < 0.35:
            return 'D'
    return 'C'
